package com.logistics.inventory;
import org.springframework.stereotype.Component;import jakarta.persistence.*;import java.util.*;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.web.bind.annotation.*;import org.springframework.amqp.rabbit.annotation.RabbitListener;import org.springframework.amqp.rabbit.core.RabbitTemplate;
@Entity class InventoryItem {@Id String sku; int available; InventoryItem(){} InventoryItem(String s,int a){sku=s;available=a;} public String getSku(){return sku;} public int getAvailable(){return available;}}
interface InventoryRepository extends JpaRepository<InventoryItem,String>{}
@RestController @RequestMapping("/api/inventory") class InventoryController {private final InventoryRepository repo; InventoryController(InventoryRepository r){repo=r;} @GetMapping List<InventoryItem> list(){return repo.findAll();} @GetMapping("/{sku}") InventoryItem get(@PathVariable String sku){return repo.findById(sku).orElse(new InventoryItem(sku,0));} @PutMapping("/{sku}") Object set(@PathVariable String sku,@RequestParam int available){if(available<0)return org.springframework.http.ResponseEntity.badRequest().body(Map.of("error","available stock cannot be negative"));return repo.save(new InventoryItem(sku,available));}}
@Component class OrderCreatedConsumer {private final InventoryRepository repo; private final RabbitTemplate rabbit; OrderCreatedConsumer(InventoryRepository r,RabbitTemplate t){repo=r;rabbit=t;} @RabbitListener(queues="inventory.order-created") void onOrder(Map<String,Object> event){String sku=String.valueOf(event.get("sku"));int qty=((Number)event.getOrDefault("quantity",1)).intValue();var item=repo.findById(sku).orElse(new InventoryItem(sku,100));boolean ok=item.available>=qty;if(ok)item.available-=qty;repo.save(item);rabbit.convertAndSend("logistics.events",ok?"InventoryReserved":"InventoryRejected",Map.of("eventType",ok?"InventoryReserved":"InventoryRejected","reserved",ok,"orderId",event.get("orderId"),"sku",sku));}}
